const ScanningMode_STATUS_Default = ScanningMode_STATUS("Default")

// Mapping from string to ScanningMode_STATUS
var scanningMode_STATUS_Values = map[string]ScanningMode_STATUS{
	"default": ScanningMode_STATUS_Default,
}

// The Vulnerability Assessment solution to be provisioned. Can be either 'TVM' or 'Qualys'
// +kubebuilder:validation:Enum={"Qualys","TVM"}
type Type string

const (
	Type_Qualys = Type("Qualys")
	Type_TVM    = Type("TVM")
)

// Mapping from string to Type
var type_Values = map[string]Type{
	"qualys": Type_Qualys,
	"tvm":    Type_TVM,
}

// The Vulnerability Assessment solution to be provisioned. Can be either 'TVM' or 'Qualys'
type Type_STATUS string

const (
	Type_STATUS_Qualys = Type_STATUS("Qualys")
	Type_STATUS_TVM    = Type_STATUS("TVM")
)

// Mapping from string to Type_STATUS
var type_STATUS_Values = map[string]Type_STATUS{
	"qualys": Type_STATUS_Qualys,
	"tvm":    Type_STATUS_TVM,
}

func init() {
	SchemeBuilder.Register(&SecurityConnector{}, &SecurityConnectorList{})
}
